def f(g):
    n,m=len(g),len(g[0])
    cnt=Counter(c for r in g for c in r)
    B=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=B]
    C=others[0] if len(others)==1 else None
    print('colors B=',B,'C=',C,'other counts',cnt)
    out=[r[:] for r in g]
    def run_bounded(g,i,j,dir_):
        if dir_=='h':
            lo=j
            while lo>=0 and g[i][lo]==B:
                lo-=1
            hi=j
            while hi<m and g[i][hi]==B:
                hi+=1
            L=lo==-1 or g[i][lo]==C
            R=hi==m or g[i][hi]==C
        else:
            lo=i
            while lo>=0 and g[lo][j]==B:
                lo-=1
            hi=i
            while hi<n and g[hi][j]==B:
                hi+=1
            L=lo==-1 or g[lo][j]==C
            R=hi==n or g[hi][j]==C
        return L and R
    for i in range(n):
        for j in range(m):
            if g[i][j]!=B: continue
            if run_bounded(g,i,j,'h') or run_bounded(g,i,j,'v'):
                out[i][j]=3
    return out,out,B,C

