from collections import Counter,deque
def enclose(g):
    n,m=len(g),len(g[0])
    cnt=Counter(c for r in g for c in r)
    B=cnt.most_common(1)[0][0]; C=[c for c in cnt if c!=B][0]
    vis=[[False]*m for _ in range(n)]
    dq=deque()
    for i in range(n):
        for j in range(m):
            if (i in(0,n-1) or j in(0,m-1)) and g[i][j]!=C and not vis[i][j]:
                vis[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for x,y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=x<n and 0<=y<m and not vis[x][y] and g[x][y]!=C:
                vis[x][y]=True; dq.append((x,y))
    out=[r[:] for r in g]
    for i in range(n):
        for j in range(m):
            if g[i][j]==B and not vis[i][j]:
                out[i][j]=3
    return out
